import heapq


def pass_route(n: int, edges: list[list[int]], stations: list[list[int]], prices: list[int]) -> int:
    k = len(prices)
    num_masks = 1 << k

    adj: list[list[tuple[int, int, int]]] = [[] for _ in range(n)]
    for u, v, cost, zone in edges:
        adj[u].append((v, cost, zone))
        adj[v].append((u, cost, zone))

    station_zones: list[list[int]] = [[] for _ in range(n)]
    for stop, z in stations:
        if z not in station_zones[stop]:
            station_zones[stop].append(z)

    inf = float("inf")
    dist = [[inf] * num_masks for _ in range(n)]
    dist[0][0] = 0
    pq: list[tuple[int, int, int]] = [(0, 0, 0)]

    while pq:
        d, u, mask = heapq.heappop(pq)
        if d > dist[u][mask]:
            continue
        if u == n - 1:
            return d

        for z in station_zones[u]:
            bit = 1 << z
            if not (mask & bit):
                nmask = mask | bit
                nd = d + prices[z]
                if nd < dist[u][nmask]:
                    dist[u][nmask] = nd
                    heapq.heappush(pq, (nd, u, nmask))

        for v, cost, zone in adj[u]:
            ride_cost = 0 if (zone != -1 and (mask & (1 << zone))) else cost
            nd = d + ride_cost
            if nd < dist[v][mask]:
                dist[v][mask] = nd
                heapq.heappush(pq, (nd, v, mask))

    return -1
